#include <Wire.h>
#include <Adafruit_Sensor.h>
#include <Adafruit_BNO055.h>
#include <utility/imumaths.h>

Adafruit_BNO055 bno = Adafruit_BNO055(55, 0x28, &Wire);

void setup() {
    Serial.begin(115200);
    if (!bno.begin()) {
        Serial.println("No BNO055 detected");
        while (1);
    }
    delay(1000);
}

void loop() {
    // Get roll & pitch from accel, read the magnetometer,
    // then compute a tilt-compensated heading.
}

hints:
sensors_event_t event;
    bno.getEvent(&event, Adafruit_BNO055::VECTOR_ACCELEROMETER);
    float roll = atan2(event.acceleration.y, event.acceleration.z);
    float pitch = atan2(-event.acceleration.x, sqrt(event.acceleration.y * event.acceleration.y + event.acceleration.z * event.acceleration.z));

bno.getEvent(&event, Adafruit_BNO055::VECTOR_MAGNETOMETER);
    float mx = event.magnetic.x;
    float my = event.magnetic.y;
    float mz = event.magnetic.z;

float Xh = mx * cos(pitch) + my * sin(roll) * sin(pitch) + mz * cos(roll) * sin(pitch);
    float Yh = my * cos(roll) - mz * sin(roll);
    float heading = atan2(-Yh, Xh) * 180 / PI;
    if (heading < 0) heading += 360;

